import { ApiCall } from "../helper/axios";
import { toast } from "../common_components/Toast/ToastUtils";
// ✅ Common module key
const MODULE_KEY = "account_summary";
class AccountSummaryService {
    async getAllAccountSummary(params, token) {
        const response = await ApiCall("POST", "/api/account-summary/view", params, {
            Authorization: token,
            modulekey: MODULE_KEY
        });
        if (response && typeof response === "object" && "data" in response) {
            return response.data;
        }
        throw new Error("Failed to fetch all clients account summary");
    }
    async getSingleAccountSummary(clientId, params, token) {
        const response = await ApiCall("POST", `/api/account-summary/view/${clientId}`, params, {
            Authorization: token,
            modulekey: MODULE_KEY
        });
        if (response && typeof response === "object" && "data" in response) {
            return response.data;
        }
        throw new Error("Failed to fetch single client account summary");
    }
    async refreshAccountSummary(token) {
        const response = await ApiCall("GET", "/api/account-summary/refresh", {}, {
            Authorization: token,
            modulekey: MODULE_KEY
        });
        if (response && "data" in response && response.status === 200) {
            toast.success("Account Summary refreshed successfully!");
            return response.data;
        }
        toast.error("Failed to refresh account summary");
        throw new Error("Failed to refresh account summary");
    }
    async hideClients(clientIds, moduleKey, hiddenBy, token) {
        const response = await ApiCall("POST", "/api/hide-client", {
            client_ids: clientIds,
            module_key: moduleKey,
            hidden_by: hiddenBy
        }, {
            Authorization: token,
            modulekey: MODULE_KEY
        });
        if (response && "data" in response && response.status === 200) {
            toast.success("Client hidden successfully");
            return response.data;
        }
        toast.error("Failed to hide clients");
        throw new Error("Failed to hide clients");
    }
    async unhideClients(clientIds, moduleKey, token) {
        const results = await Promise.all(clientIds.map(clientId => ApiCall("DELETE", `/api/hide-client/${clientId}?module_key=${moduleKey}`, {}, {
            Authorization: token,
            modulekey: MODULE_KEY
        })));
        const unhiddenIds = results
            .filter(r => r && 'data' in r && r.status === 200 && r.data?.success)
            .map(r => ('data' in r && r.data?.data?.client_id) ? r.data.data.client_id : '')
            .filter(id => id !== '');
        if (unhiddenIds.length > 0) {
            toast.success(`${unhiddenIds.length} client(s) unhidden successfully`);
        }
        else {
            toast.error("Failed to unhide clients");
        }
        return {
            success: true,
            message: `${unhiddenIds.length} client(s) unhidden successfully`,
            unhiddenClientIds: unhiddenIds
        };
    }
    async getHiddenClients(moduleKey, token) {
        const response = await ApiCall("GET", `/api/hide-client?module_key=${moduleKey}`, "", {
            Authorization: token,
            modulekey: MODULE_KEY
        });
        if (response && "data" in response && response.status === 200) {
            return response.data;
        }
        throw new Error("Failed to fetch hidden clients");
    }
    async triggerHourlyCron(params, token) {
        const response = await ApiCall("POST", "/api/cron/trigger-hourly", params, {
            Authorization: token,
            modulekey: MODULE_KEY
        });
        if (response && "data" in response && response.status === 200) {
            return response.data;
        }
        throw new Error("Failed to trigger hourly cron");
    }
    async getCronStatus(token) {
        const response = await ApiCall("GET", "/api/cron/status", "", {
            Authorization: token,
            modulekey: MODULE_KEY
        });
        if (response && "data" in response && response.status === 200) {
            return response.data;
        }
        throw new Error("Failed to fetch cron status");
    }
    async getSportPerformanceReport(params, token) {
        const response = await ApiCall("POST", "/api/performance/reportV2", params, {
            Authorization: token,
            modulekey: MODULE_KEY
        });
        if (response && "data" in response && response.status === 200) {
            return response.data;
        }
        throw new Error("Failed to fetch performance report");
    }
    async getPerformanceEntities(params, token) {
        const response = await ApiCall("GET", "/api/performance", params, {
            Authorization: token,
            modulekey: MODULE_KEY
        });
        if (response && "data" in response && response.status === 200) {
            return response.data;
        }
        throw new Error("Failed to fetch performance entities");
    }
    async getTeamPerformanceReport(clientId, params, token) {
        return await ApiCall("GET", `/api/team-performance/${clientId}`, params, {
            Authorization: token,
            modulekey: MODULE_KEY
        });
    }
}
export const accountSummaryService = new AccountSummaryService();
