import { createSlice, createAsyncThunk } from "@reduxjs/toolkit";
import { utilityService } from "../services/utility.service";
/**
 * Initial state
 */
const initialState = {
    activeClients: [],
    loading: false,
    error: null,
};
/**
 * Async thunk: Fetch active clients
 */
export const fetchActiveClients = createAsyncThunk("utility/fetchActiveClients", async (token, { rejectWithValue }) => {
    try {
        const response = await utilityService.getActiveClients(token);
        return response.data; // <-- ONLY ARRAY return karna!
    }
    catch (err) {
        return rejectWithValue(err.message);
    }
});
/**
 * Utility Slice
 */
const utilitySlice = createSlice({
    name: "utility",
    initialState,
    reducers: {
        clearActiveClients: (state) => {
            state.activeClients = [];
            state.error = null;
        },
    },
    extraReducers: (builder) => {
        builder
            // Fetch active clients
            .addCase(fetchActiveClients.pending, (state) => {
            state.loading = true;
            state.error = null;
        })
            .addCase(fetchActiveClients.fulfilled, (state, action) => {
            state.loading = false;
            state.activeClients = action.payload;
        })
            .addCase(fetchActiveClients.rejected, (state, action) => {
            state.loading = false;
            state.error = action.payload;
        });
    },
});
// Actions
export const { clearActiveClients } = utilitySlice.actions;
// Selectors
export const selectActiveClients = (state) => state.utility.activeClients;
export const selectUtilityLoading = (state) => state.utility.loading;
export const selectUtilityError = (state) => state.utility.error;
export default utilitySlice.reducer;
