import { createSlice } from "@reduxjs/toolkit";
const initialState = {
    moduleAccess: {},
    rolePermissions: {},
    userPermissions: null,
};
const permissionsSlice = createSlice({
    name: "permissions",
    initialState,
    reducers: {
        /**
         * Set module access for a specific module
         */
        setModuleAccess: (state, action) => {
            const { moduleKey, hasAccess } = action.payload;
            state.moduleAccess[moduleKey] = hasAccess;
        },
        /**
         * Set permissions for a specific role
         */
        setRolePermissions: (state, action) => {
            const { roleId, permissions } = action.payload;
            state.rolePermissions[roleId] = permissions;
        },
        /**
         * Update user's effective permissions (typically set after login or role change)
         */
        setUserPermissions: (state, action) => {
            state.userPermissions = action.payload;
            // Update module access based on user permissions
            if (action.payload) {
                Object.keys(action.payload).forEach((moduleKey) => {
                    state.moduleAccess[moduleKey] = action.payload[moduleKey].access === true;
                });
            }
        },
        /**
         * Clear all permissions (on logout)
         */
        clearPermissions: (state) => {
            state.moduleAccess = {};
            state.rolePermissions = {};
            state.userPermissions = null;
        },
    },
});
export const { setModuleAccess, setRolePermissions, setUserPermissions, clearPermissions, } = permissionsSlice.actions;
// Selectors
export const selectModuleAccess = (state) => state.permissions.moduleAccess;
export const selectRolePermissions = (state) => state.permissions.rolePermissions;
export const selectUserPermissions = (state) => state.permissions.userPermissions;
export const selectHasModuleAccess = (moduleKey) => (state) => state.permissions.moduleAccess[moduleKey] === true;
export default permissionsSlice.reducer;
